import { createTheme } from '@mui/material/styles';

import '@fontsource/prompt/300.css';
import '@fontsource/prompt/400.css';
import '@fontsource/prompt/700.css';


const theme = createTheme({
  palette: {
    primary: {
      main: '#4BAF9E', // เขียวแก้วเข้ม
      contrastText: '#ffffff',
    },
    secondary: {
      main: '#D88FA0', // ชมพูพาสเทลเข้ม
    },
    background: {
      default: '#DDE4E1', // เทาอมเขียวอ่อน
      paper: '#FFFFFF',
    },
    error: {
      main: '#D46A6A', // แดงพาสเทลเข้ม
    },
    warning: {
      main: '#F2C94C', // เหลืองพาสเทลเข้ม
    },
    info: {
      main: '#5DADE2', // ฟ้าอมเทาเข้ม
    },
    success: {
      main: '#58D68D', // เขียวมิ้นต์เข้ม
    },
    text: {
      primary: '#2C3E50',
      secondary: '#566573',
    },
  },
  typography: {
    fontFamily: 'Prompt, sans-serif',
  },
  components: {

    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          textTransform: 'none',
          fontWeight: 'bold',
          padding: '8px 16px',
        },
        containedPrimary: {
          backgroundColor: '#4CAF50',
          color: '#fff',
          '&:hover': {
            backgroundColor: '#388E3C',
          },
        },
        outlinedPrimary: {
          borderColor: '#4CAF50',
          color: '#4CAF50',
          '&:hover': {
            backgroundColor: '#E8F5E9',
          },
        },
      },
    },
  }
});


export default theme;
